import fs from'node:fs';import crypto from'node:crypto';import{chromium}from'playwright';
const out=process.env.PROBE_OUTPUT;fs.mkdirSync(out,{recursive:true});const path='/system/files/2026-06/20260630_AS180_revalorisation_2025.pdf';const hosts=['acpr.banque-france.fr','www.banque-france.fr'];const browser=await chromium.launch({headless:true,executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome'});const attempts=[];
try{for(const host of hosts){const context=await browser.newContext({acceptDownloads:true,locale:'fr-FR'}),page=await context.newPage(),url='https://'+host+path;const attempt={url,startedAt:new Date().toISOString(),mode:'Ordinary installed Chrome, no stealth, no CAPTCHA handling, no injected cookies'};let downloaded;const done=new Promise(resolve=>page.on('download',async dl=>{try{const file=out+'/'+host+'.pdf';await dl.saveAs(file);downloaded=file}catch{}finally{resolve()}}));try{await page.goto('https://'+host+'/fr',{waitUntil:'domcontentloaded',timeout:25000})}catch(e){attempt.homeError=e.message.split('\n')[0]}
try{const response=await page.goto(url,{waitUntil:'domcontentloaded',timeout:25000});attempt.status=response?.status();attempt.finalUrl=response?.url();attempt.contentType=response?.headers()['content-type'];if(response?.status()===200){const final=new URL(response.url());if(!hosts.includes(final.hostname)||final.pathname!==path)throw Error('Redirect outside exact official document scope');try{const body=await response.body();if(body.subarray(0,5).toString()==='%PDF-'){const file=out+'/'+host+'.pdf';fs.writeFileSync(file,body);downloaded=file}}catch(e){attempt.responseBodyError=e.message.split('\n')[0]}}}catch(e){attempt.navigationError=e.message.split('\n')[0]}
if(!downloaded)await Promise.race([done,new Promise(resolve=>setTimeout(resolve,3000))]);if(downloaded){const body=fs.readFileSync(downloaded);if(body.length>8e6||body.subarray(0,5).toString()!=='%PDF-')throw Error('Bounded official PDF not obtained');attempt.pdfFile=downloaded;attempt.bytes=body.length;attempt.sha256=crypto.createHash('sha256').update(body).digest('hex');attempt.status='pdf-acquired'}else attempt.result='No official PDF acquired; access remains unqualified';attempt.completedAt=new Date().toISOString();attempts.push(attempt);await context.close();}}
finally{await browser.close();fs.writeFileSync(out+'/attempts.json',JSON.stringify({checkedAt:new Date().toISOString(),attempts,scope:'Isolated ordinary-browser source qualification; never a production refresh or cron'},null,2))}console.log(attempts.map(a=>({host:new URL(a.url).hostname,status:a.status,pdf:!!a.pdfFile})))
